import json,pathlib
r=pathlib.Path(__file__).resolve().parent.parent
schema=json.loads((r/'bindings/bom-abi.json').read_text())
lines=['#include "../../bindings/bom_client.h"','#define CHECK(x) do { if(!(x)) return __LINE__; } while(0)','#define OFFSET(t,f) ((unsigned int)(unsigned long long)&(((t*)0)->f))','int main(void) {',' unsigned long long handle=0,stale=0; unsigned int i;',' BomCreateInfo create={sizeof(BomCreateInfo),1,0,0};',' BomSample sample={0};']
for i,(name,fields) in enumerate(schema['structs'].items()):
 lines+=[' CHECK(bom_debug_layout('+str(i)+',0)==sizeof('+name+'));',' CHECK(bom_debug_layout('+str(i)+',1)==__alignof('+name+'));']
 lines+=[' CHECK(bom_debug_layout('+str(i)+','+str(j+2)+')==OFFSET('+name+','+field+'));' for j,(field,_) in enumerate(fields)]
lines+=[' CHECK(bom_abi_version()==1 && bom_build_tag()!=0);',' CHECK(bom_client_create(0,&handle)==2 && bom_client_create(&create,0)==2);',' for(i=0;i<100;i++) {','  CHECK(bom_client_create(&create,&handle)==0);','  sample.struct_size=sizeof(sample);sample.version=1;','  CHECK(bom_client_acquire_sample(handle,&sample)==0);','  CHECK(bom_client_destroy(handle)==3);','  CHECK(bom_client_release_sample(handle,sample.sample_sequence)==0);','  CHECK(bom_client_ack_sample(handle,sample.sample_sequence)==0);','  stale=handle;CHECK(bom_client_destroy(handle)==0);','  CHECK(bom_client_destroy(stale)==1);',' }',' create.struct_size=0;CHECK(bom_client_create(&create,&handle)==2);create.struct_size=sizeof(create);', ' create.version=2;CHECK(bom_client_create(&create,&handle)==2);create.version=1;', ' CHECK(bom_client_create(&create,&handle)==0);', ' CHECK(bom_client_connect(handle,0)==2);', ' CHECK(bom_client_acquire_sample(handle,0)==2);', ' { BomConnectInfo connect={0};connect.struct_size=sizeof(connect);connect.version=1;connect.ipv4=0x7f000001;connect.port=1;', '   connect.token_length=129;CHECK(bom_client_connect(handle,&connect)==2);connect.token_length=0;', '   CHECK(bom_client_connect(handle,&connect)==0);', '   for(i=0;i<256;i++)CHECK(bom_client_set_held_input(handle,(double)i,0)==0);', '   CHECK(bom_client_set_held_input(handle,256,0)==8);', '   for(i=0;i<64;i++)CHECK(bom_client_enqueue_jump(handle,(double)i)==0);', '   CHECK(bom_client_enqueue_jump(handle,64)==8);', '   for(i=0;i<64;i++)CHECK(bom_client_enqueue_action(handle,(double)i,0,1)==0);', '   CHECK(bom_client_enqueue_action(handle,64,0,1)==8);', ' }', ' CHECK(bom_client_destroy(handle)==0);', ' return 0;','}']
(r/'tests/interop/layout_test.c').write_text('\n'.join(lines)+'\n',encoding='utf-8')
